/* ============================================================
   NEON FIST — Sunset Duel
   ============================================================ */
@font-face {
  font-family: 'Bebas Neue';
  src: url('../assets/fonts/bebas.woff2') format('woff2');
  font-weight: 400; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('../assets/fonts/rajdhani-500.woff2') format('woff2');
  font-weight: 500; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('../assets/fonts/rajdhani-600.woff2') format('woff2');
  font-weight: 600; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('../assets/fonts/rajdhani-700.woff2') format('woff2');
  font-weight: 700; font-style: normal; font-display: swap;
}

:root {
  --ink: #08050f;
  --ink-2: #120b22;
  --paper: #f6efe2;
  --crimson: #ff3558;
  --crimson-deep: #b81234;
  --gold: #ffc857;
  --cyan: #3fe6ff;
  --violet: #8b5cff;
  --raj: 'Rajdhani', 'DejaVu Sans', sans-serif;
  --bebas: 'Bebas Neue', 'DejaVu Sans', sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0; padding: 0;
  width: 100%; height: 100%;
  background: #06040d;
  overflow: hidden;
  color: var(--paper);
  font-family: var(--raj);
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
  user-select: none;
  -webkit-user-select: none;
}

#app {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100vh;
  height: 100dvh;
  width: 100vw;
  background:
    radial-gradient(ellipse at 50% 30%, #1a0e2e 0%, #08050f 55%, #030208 100%);
}

#frame {
  position: relative;
  width: min(100vw, calc(100dvh * 16 / 9));
  aspect-ratio: 16 / 9;
  overflow: hidden;
  background: #08050f;
  box-shadow: 0 0 0 1px rgba(255, 210, 160, 0.08), 0 30px 90px -20px #000;
  flex: none;
}
#frame::after {
  content: '';
  position: absolute; inset: 0;
  pointer-events: none;
  z-index: 5;
  background:
    radial-gradient(ellipse at 50% 45%, transparent 45%, rgba(4,2,10,0.55) 100%);
  mix-blend-mode: multiply;
}

canvas#game {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: auto;
}

/* ============================================================
   SCREENS
   ============================================================ */
.screen {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: max(16px, env(safe-area-inset-top)) 18px max(16px, env(safe-area-inset-bottom));
  background:
    radial-gradient(ellipse at 50% 30%, rgba(28, 13, 48, 0.72) 0%, rgba(6, 3, 15, 0.9) 55%, rgba(2, 1, 6, 0.96) 100%);
  opacity: 1;
  transition: opacity 220ms ease;
  overflow: hidden;
}
.screen.hidden { display: none; }
.screen::before {
  content: '';
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.02) 1px, transparent 1px);
  background-size: 100% 3px, 100% 100%;
  pointer-events: none;
  opacity: 0.5;
}

.title-wrap {
  position: relative;
  z-index: 1;
  width: min(94vw, 760px);
  max-height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  animation: rise 520ms cubic-bezier(.2,.8,.2,1) both;
}

@keyframes rise {
  from { opacity: 0; transform: translateY(14px) scale(.985); }
  to { opacity: 1; transform: none; }
}

.kicker {
  font-family: var(--raj);
  font-weight: 700;
  letter-spacing: 0.42em;
  font-size: clamp(9px, 1.25vmin, 14px);
  color: #ffd9a0;
  display: flex;
  align-items: center;
  gap: 12px;
  text-transform: uppercase;
  opacity: 0.9;
}
.kicker .rule {
  display: block;
  width: clamp(26px, 6vmin, 70px);
  height: 1px;
  background: linear-gradient(90deg, transparent, #ffb15c, transparent);
}

.logo {
  font-family: var(--bebas);
  font-weight: 400;
  font-size: clamp(58px, 13.5vmin, 138px);
  line-height: 0.84;
  margin: 8px 0 4px;
  letter-spacing: 0.015em;
  display: flex;
  gap: 0.18em;
  transform: skewX(-6deg);
  filter: drop-shadow(0 8px 0 rgba(120, 8, 40, 0.55)) drop-shadow(0 18px 40px rgba(255, 53, 88, 0.22));
}
.logo-a {
  background: linear-gradient(180deg, #fff6e6 8%, #ffd190 45%, #ff8a4c 92%);
  -webkit-background-clip: text; background-clip: text;
  -webkit-text-fill-color: transparent; color: transparent;
}
.logo-b {
  background: linear-gradient(180deg, #ffe7f2 4%, #ff6688 42%, #c1123d 95%);
  -webkit-background-clip: text; background-clip: text;
  -webkit-text-fill-color: transparent; color: transparent;
}
.tagline {
  margin: 6px 0 0;
  font-size: clamp(11px, 1.7vmin, 16px);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #cdb9d8;
  font-weight: 600;
}

.matchup {
  display: flex;
  align-items: center;
  gap: clamp(10px, 2.4vmin, 24px);
  margin: clamp(14px, 2.6vmin, 26px) 0 clamp(10px, 2vmin, 20px);
  width: 100%;
  justify-content: center;
}
.fighter-card {
  display: flex;
  align-items: center;
  gap: clamp(8px, 1.4vmin, 14px);
  padding: clamp(7px, 1.2vmin, 12px) clamp(10px, 1.6vmin, 18px);
  background: linear-gradient(135deg, rgba(255,255,255,0.055), rgba(255,255,255,0.015));
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 4px;
  min-width: clamp(120px, 22vmin, 230px);
  text-align: left;
  clip-path: polygon(0 0, 100% 0, calc(100% - 10px) 100%, 0 100%);
}
.fighter-card.p2 {
  clip-path: polygon(10px 0, 100% 0, 100% 100%, 0 100%);
  text-align: right;
  justify-content: flex-end;
  background: linear-gradient(225deg, rgba(63,230,255,0.07), rgba(255,255,255,0.015));
  border-color: rgba(63, 230, 255, 0.18);
}
.fighter-card.p1 { border-left: 3px solid var(--crimson); }
.fighter-card.p2 { border-right: 3px solid var(--cyan); }
.ftag { font-size: clamp(7px, 1.05vmin, 10px); letter-spacing: 0.28em; color: #a796b6; font-weight: 700; }
.fname { font-family: var(--bebas); font-size: clamp(20px, 3.2vmin, 34px); line-height: 1; letter-spacing: 0.06em; }
.p1 .fname { color: #ff8b9e; }
.p2 .fname { color: #8beeff; }
.fsub { font-size: clamp(8px, 1.2vmin, 12px); letter-spacing: 0.16em; text-transform: uppercase; color: #8f7fa2; font-weight: 600; }
.portrait {
  width: clamp(34px, 5.6vmin, 54px); height: clamp(34px, 5.6vmin, 54px);
  border-radius: 50%;
  display: grid; place-items: center;
  font-family: var(--bebas);
  font-size: clamp(20px, 3.2vmin, 32px);
  color: #120a18;
  flex: none;
  border: 2px solid rgba(255,255,255,0.28);
}
.portrait-kaze { background: radial-gradient(circle at 35% 25%, #ffd6a8, #ff6d55 55%, #a0122f); }
.portrait-ren { background: radial-gradient(circle at 35% 25%, #d8fbff, #4bc6e0 55%, #16506f); }
.vs {
  font-family: var(--bebas);
  font-size: clamp(22px, 4vmin, 44px);
  color: #ffb45c;
  transform: skewX(-8deg);
  text-shadow: 0 0 18px rgba(255, 140, 60, 0.5);
  flex: none;
}

.difficulty {
  display: flex; align-items: center; gap: 12px;
  margin-bottom: clamp(12px, 2.2vmin, 22px);
  flex-wrap: wrap; justify-content: center;
}
.dl { font-size: clamp(8px, 1.15vmin, 11px); letter-spacing: 0.32em; color: #8f7fa2; font-weight: 700; }
.segmented {
  display: flex;
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.09);
  border-radius: 3px;
  padding: 3px;
  gap: 3px;
}
.segmented button {
  font-family: var(--raj);
  font-weight: 700;
  font-size: clamp(9px, 1.3vmin, 13px);
  letter-spacing: 0.18em;
  color: #b7a6c6;
  background: transparent;
  border: 0;
  padding: clamp(4px, 0.9vmin, 8px) clamp(9px, 1.8vmin, 18px);
  border-radius: 2px;
  cursor: pointer;
  transition: all 140ms ease;
}
.segmented button:hover { color: #fff; background: rgba(255,255,255,0.06); }
.segmented button.active {
  color: #1a0910;
  background: linear-gradient(180deg, #ffd483, #ff9a4e);
  box-shadow: 0 0 16px rgba(255, 160, 70, 0.4);
}

.big-btn {
  font-family: var(--raj);
  font-weight: 700;
  font-size: clamp(14px, 2vmin, 20px);
  letter-spacing: 0.22em;
  color: #1a040a;
  border: 0;
  cursor: pointer;
  padding: clamp(11px, 1.9vmin, 17px) clamp(28px, 5vmin, 58px);
  background: linear-gradient(180deg, #ffe7b0 0%, #ffbf63 32%, #ff5d5d 100%);
  clip-path: polygon(14px 0, 100% 0, calc(100% - 14px) 100%, 0 100%);
  box-shadow: 0 0 0 1px rgba(255, 220, 160, 0.45), 0 12px 34px -8px rgba(255, 70, 80, 0.5);
  transition: transform 120ms ease, filter 120ms ease;
  display: inline-flex; align-items: center; gap: 10px;
  white-space: nowrap;
}
.big-btn:hover { transform: translateY(-1px); filter: brightness(1.07); }
.big-btn:active { transform: translateY(1px) scale(0.99); }
.big-btn.small { font-size: clamp(12px, 1.6vmin, 16px); padding: clamp(9px, 1.4vmin, 13px) clamp(22px, 3.6vmin, 40px); }

.ghost-btn {
  font-family: var(--raj);
  font-weight: 700;
  font-size: clamp(10px, 1.4vmin, 14px);
  letter-spacing: 0.2em;
  color: #d9c9e6;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.14);
  padding: clamp(9px, 1.4vmin, 13px) clamp(22px, 3.6vmin, 40px);
  cursor: pointer;
  transition: all 130ms ease;
  clip-path: polygon(9px 0, 100% 0, calc(100% - 9px) 100%, 0 100%);
}
.ghost-btn:hover { background: rgba(255,255,255,0.09); color: #fff; }

.keycap {
  display: inline-block;
  font-family: var(--raj);
  font-size: 0.62em;
  font-weight: 700;
  letter-spacing: 0.06em;
  padding: 2px 5px 1px;
  border: 1px solid rgba(20, 6, 10, 0.4);
  border-bottom-width: 2px;
  border-radius: 2px;
  background: rgba(255,255,255,0.35);
  color: #2a0810;
  vertical-align: middle;
}
.keycap.inline { margin-left: 4px; }

.controls-help {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: clamp(5px, 1vmin, 9px) clamp(8px, 1.6vmin, 18px);
  margin-top: clamp(12px, 2.2vmin, 22px);
  font-size: clamp(8px, 1.15vmin, 11px);
  letter-spacing: 0.12em;
  color: #b2a1c2;
  font-weight: 600;
  text-transform: uppercase;
