export const TAU = Math.PI * 2;

export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const invLerp = (a, b, v) => (b === a ? 0 : (v - a) / (b - a));
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a);
export const pick = (arr) => arr[(Math.random() * arr.length) | 0];
export const sign = (v) => (v < 0 ? -1 : 1);

export const easeOut = (t) => 1 - Math.pow(1 - t, 3);
export const easeIn = (t) => t * t * t;
export const easeInOut = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
export const easeOutBack = (t) => {
  const c = 1.70158;
  return 1 + (c + 1) * Math.pow(t - 1, 3) + c * Math.pow(t - 1, 2);
};

export function rot(x, y, a) {
  const c = Math.cos(a);
  const s = Math.sin(a);
  return { x: x * c - y * s, y: x * s + y * c };
}

export function shade(hex, amt) {
  const h = hex.replace('#', '');
  const n = parseInt(h.length === 3 ? h.split('').map((c) => c + c).join('') : h, 16);
  let r = (n >> 16) & 255;
  let g = (n >> 8) & 255;
  let b = n & 255;
  r = clamp(Math.round(r + amt), 0, 255);
  g = clamp(Math.round(g + amt), 0, 255);
  b = clamp(Math.round(b + amt), 0, 255);
  return `rgb(${r},${g},${b})`;
}

export function rgba(hex, a) {
  const h = hex.replace('#', '');
  const n = parseInt(h.length === 3 ? h.split('').map((c) => c + c).join('') : h, 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
}

/** Two-bone IK: returns the joint position. bend +1 / -1 selects the elbow side. */
export function ik(root, target, len1, len2, bend) {
  const dx = target.x - root.x;
  const dy = target.y - root.y;
  let dist = Math.hypot(dx, dy);
  const min = Math.abs(len1 - len2) + 0.01;
  const max = len1 + len2 - 0.01;
  const d = clamp(dist, min, max);
  const base = Math.atan2(dy, dx);
  const cosA = (len1 * len1 + d * d - len2 * len2) / (2 * len1 * d);
  const a = Math.acos(clamp(cosA, -1, 1));
  const ang = base + bend * a;
  return { x: root.x + Math.cos(ang) * len1, y: root.y + Math.sin(ang) * len1 };
}

export function rectsOverlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

export function pointInRect(px, py, r) {
  return px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h;
}

/* Tiny synthesized sound kit — no external assets. */
export class Sfx {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.noiseBuf = null;
    this.musicTimer = null;
    this.musicStep = 0;
    this.musicOn = false;
    this.lastWhoosh = 0;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return;
    }
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.55;
      this.master.connect(this.ctx.destination);
      const len = Math.floor(this.ctx.sampleRate * 1.2);
      const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const data = buf.getChannelData(0);
      for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
      this.noiseBuf = buf;
    } catch (e) {
      this.ctx = null;
    }
  }

  toggle() {
    this.muted = !this.muted;
    if (this.master) this.master.gain.value = this.muted ? 0 : 0.55;
    return this.muted;
  }

  now() {
    return this.ctx ? this.ctx.currentTime : 0;
  }

  noise({ dur = 0.15, gain = 0.2, type = 'bandpass', f0 = 800, f1 = 300, q = 1, delay = 0 } = {}) {
    if (!this.ctx || this.muted) return;
    const t = this.now() + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuf;
    const filt = this.ctx.createBiquadFilter();
    filt.type = type;
    filt.Q.value = q;
    filt.frequency.setValueAtTime(f0, t);
    filt.frequency.exponentialRampToValueAtTime(Math.max(40, f1), t + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filt).connect(g).connect(this.master);
    src.start(t);
    src.stop(t + dur + 0.05);
  }

  tone({ f0 = 440, f1 = f0, dur = 0.2, type = 'sine', gain = 0.18, delay = 0, attack = 0.008 } = {}) {
    if (!this.ctx || this.muted) return;
    const t = this.now() + delay;
    const osc = this.ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, f0), t);
    if (f1 !== f0) osc.frequency.exponentialRampToValueAtTime(Math.max(20, f1), t + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g).connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.04);
  }

  whoosh(power = 1) {
    const n = this.now();
    if (n - this.lastWhoosh < 0.04) return;
    this.lastWhoosh = n;
    this.noise({ dur: 0.11 + power * 0.05, gain: 0.05 + power * 0.04, type: 'bandpass', f0: 500, f1: 1700, q: 1.4 });
  }

  hit(power = 1) {
    this.noise({ dur: 0.12 + power * 0.07, gain: 0.22 + power * 0.15, type: 'lowpass', f0: 1900, f1: 200, q: 0.8 });
    this.tone({ f0: 130 + power * 30, f1: 52, dur: 0.16 + power * 0.06, type: 'triangle', gain: 0.24 + power * 0.1 });
    if (power > 0.7) this.tone({ f0: 800, f1: 300, dur: 0.09, type: 'square', gain: 0.05 });
  }

  block() {
    this.noise({ dur: 0.09, gain: 0.16, type: 'highpass', f0: 1800, f1: 1200, q: 1 });
    this.tone({ f0: 700, f1: 520, dur: 0.08, type: 'square', gain: 0.05 });
  }

  jump() {
    this.tone({ f0: 220, f1: 420, dur: 0.1, type: 'sine', gain: 0.05 });
  }

  land() {
    this.noise({ dur: 0.1, gain: 0.1, type: 'lowpass', f0: 500, f1: 120 });
  }

  fireball() {
    this.tone({ f0: 180, f1: 720, dur: 0.32, type: 'sawtooth', gain: 0.1 });
    this.noise({ dur: 0.4, gain: 0.1, type: 'bandpass', f0: 380, f1: 1600, q: 2 });
  }

  uppercut() {
    this.tone({ f0: 150, f1: 900, dur: 0.28, type: 'square', gain: 0.08 });
    this.noise({ dur: 0.3, gain: 0.12, type: 'bandpass', f0: 300, f1: 2000, q: 1.5 });
  }

  spin() {
    this.noise({ dur: 0.5, gain: 0.12, type: 'bandpass', f0: 250, f1: 1400, q: 3 });
    this.tone({ f0: 300, f1: 500, dur: 0.35, type: 'triangle', gain: 0.04 });
  }

  ko() {
    this.tone({ f0: 240, f1: 45, dur: 0.9, type: 'sawtooth', gain: 0.2 });
    this.noise({ dur: 0.8, gain: 0.24, type: 'lowpass', f0: 2400, f1: 90 });
    this.tone({ f0: 70, f1: 40, dur: 1.1, type: 'sine', gain: 0.24, delay: 0.03 });
  }

  roundStart() {
    this.tone({ f0: 440, dur: 0.08, type: 'square', gain: 0.06 });
    this.tone({ f0: 660, dur: 0.14, type: 'square', gain: 0.06, delay: 0.1 });
  }

  fight() {
    [330, 440, 554, 660].forEach((f, i) =>
      this.tone({ f0: f, dur: 0.16, type: 'sawtooth', gain: 0.055, delay: i * 0.055 }));
  }

  win() {
    [392, 523, 659, 784, 1046].forEach((f, i) =>
      this.tone({ f0: f, dur: 0.32, type: 'triangle', gain: 0.09, delay: i * 0.09 }));
  }

  lose() {
    [392, 349, 311, 233].forEach((f, i) =>
      this.tone({ f0: f, dur: 0.4, type: 'triangle', gain: 0.08, delay: i * 0.12 }));
  }

  ui() {
    this.tone({ f0: 700, f1: 900, dur: 0.05, type: 'square', gain: 0.035 });
  }

  superReady() {
    this.tone({ f0: 523, dur: 0.12, type: 'triangle', gain: 0.07 });
    this.tone({ f0: 784, dur: 0.18, type: 'triangle', gain: 0.07, delay: 0.1 });
  }

  startMusic() {
    if (!this.ctx || this.musicOn) return;
    this.musicOn = true;
    this.musicStep = 0;
    this.musicTimer = setInterval(() => this.musicTick(), 250);
  }

  stopMusic() {
    this.musicOn = false;
    if (this.musicTimer) clearInterval(this.musicTimer);
    this.musicTimer = null;
  }

  musicTick() {
    if (!this.ctx || this.muted || !this.musicOn) return;
    const s = this.musicStep % 16;
    const bass = [55, 55, 65.4, 55, 49, 49, 46.2, 55, 55, 55, 65.4, 73.4, 65.4, 55, 49, 46.2];
    if (s % 2 === 0) {
      this.tone({ f0: bass[s], dur: 0.2, type: 'triangle', gain: 0.05 });
      this.tone({ f0: bass[s] * 2, dur: 0.12, type: 'sine', gain: 0.02 });
    }
    if (s % 4 === 2) this.noise({ dur: 0.05, gain: 0.02, type: 'highpass', f0: 6000, f1: 5000 });
    if (s === 0 || s === 8) this.tone({ f0: 120, f1: 45, dur: 0.22, type: 'sine', gain: 0.1 });
    this.musicStep++;
  }
}

const KEYMAP = {
  left: ['KeyA', 'ArrowLeft'],
  right: ['KeyD', 'ArrowRight'],
  up: ['KeyW', 'ArrowUp'],
  down: ['KeyS', 'ArrowDown'],
  lp: ['KeyJ'],
  hp: ['KeyK'],
  kick: ['KeyL'],
  fire: ['KeyU'],
  dp: ['KeyI'],
  spin: ['KeyO'],
  pause: ['KeyP', 'Escape'],
  mute: ['KeyM'],
  start: ['Enter', 'Space'],
};

const CODE_TO_ACTION = {};
for (const [action, codes] of Object.entries(KEYMAP)) {
  for (const code of codes) CODE_TO_ACTION[code] = action;
}

export class InputManager {
  constructor() {
    this.kb = new Set();
    this.kbPressed = new Set();
    this.ts = new Set();
    this.tsPressed = new Set();
    this.pad = { x: 0, y: 0, active: false, pointerId: null };
    this.touchMode = false;
    this.onFirstGesture = null;
    this.padEl = null;
    this.knobEl = null;
    this._bind();
  }

  _bind() {
    const isTouchDevice =
      (window.matchMedia && window.matchMedia('(pointer: coarse)').matches) ||
      (navigator.maxTouchPoints || 0) > 0 ||
      window.innerWidth < 760;
    if (isTouchDevice) this.enableTouchMode();

    window.addEventListener('keydown', (e) => {
      const action = CODE_TO_ACTION[e.code];
      if (e.repeat) {
        if (action) e.preventDefault();
        return;
      }
      if (action) {
        e.preventDefault();
        this.kb.add(action);
        this.kbPressed.add(action);
        this._gesture();
      }
    });
    window.addEventListener('keyup', (e) => {
      const action = CODE_TO_ACTION[e.code];
      if (action) {
        e.preventDefault();
        this.kb.delete(action);
      }
    });
    window.addEventListener('blur', () => {
      this.kb.clear();
      this.ts.clear();
      this.resetPad();
      this.padEl?.classList.remove('active');
    });
    window.addEventListener('pointerdown', () => this._gesture(), { passive: true });
    window.addEventListener('touchstart', () => this.enableTouchMode(), { passive: true });
    window.addEventListener('contextmenu', (e) => {
      if (e.target.closest('#touch')) e.preventDefault();
    });
  }

  enableTouchMode() {
    if (this.touchMode) return;
    this.touchMode = true;
    document.body.classList.add('is-touch');
  }

  _gesture() {
    if (this.onFirstGesture) {
      const fn = this.onFirstGesture;
      this.onFirstGesture = null;
      try { fn(); } catch (e) { /* ignore */ }
    }
  }

  attachTouch() {
    this.padEl = document.getElementById('pad');
    this.knobEl = document.getElementById('knob');
    if (!this.padEl) return;

    const rect = () => this.padEl.getBoundingClientRect();

    const update = (clientX, clientY) => {
      const r = rect();
      const cx = r.left + r.width / 2;
      const cy = r.top + r.height / 2;
      let dx = (clientX - cx) / (r.width * 0.42);
      let dy = (clientY - cy) / (r.height * 0.42);
      const len = Math.hypot(dx, dy);
      if (len > 1) { dx /= len; dy /= len; }
      this.pad.x = dx;
      this.pad.y = dy;
      const wasUp = this.ts.has('up');
      const wasDown = this.ts.has('down');
      this.ts.delete('left'); this.ts.delete('right'); this.ts.delete('up'); this.ts.delete('down');
      if (dx < -0.28) this.ts.add('left');
      if (dx > 0.28) this.ts.add('right');
      if (dy < -0.4) this.ts.add('up');
      if (dy > 0.36) this.ts.add('down');
      if (!wasUp && this.ts.has('up')) this.tsPressed.add('up');
      if (!wasDown && this.ts.has('down')) this.tsPressed.add('down');
      if (this.knobEl) {
        const px = Math.max(-1, Math.min(1, dx));
        const py = Math.max(-1, Math.min(1, dy));
        this.knobEl.style.transform = `translate(calc(-50% + ${px * 38}%), calc(-50% + ${py * 38}%))`;
        this.knobEl.classList.toggle('active', len > 0.2);
      }
    };

    const end = () => {
      this.pad.active = false;
      this.pad.pointerId = null;
      this.pad.x = 0; this.pad.y = 0;
      this.ts.delete('left'); this.ts.delete('right'); this.ts.delete('up'); this.ts.delete('down');
      if (this.knobEl) {
        this.knobEl.style.transform = 'translate(-50%, -50%)';
        this.knobEl.classList.remove('active');
      }
      this.padEl.classList.remove('active');
    };

    this.padEl.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      this.enableTouchMode();
      this._gesture();
      this.pad.active = true;
      this.pad.pointerId = e.pointerId;
      this.padEl.classList.add('active');
      this.padEl.setPointerCapture(e.pointerId);
      update(e.clientX, e.clientY);
    });
    this.padEl.addEventListener('pointermove', (e) => {
      if (!this.pad.active || e.pointerId !== this.pad.pointerId) return;
      e.preventDefault();
      update(e.clientX, e.clientY);
    });
    for (const ev of ['pointerup', 'pointercancel', 'lostpointercapture']) {
      this.padEl.addEventListener(ev, (e) => {
        if (this.pad.pointerId !== null && e.pointerId !== this.pad.pointerId) return;
        end();
      });
    }

    document.querySelectorAll('.tbtn').forEach((btn) => {
      const raw = btn.dataset.action;
      const action = raw === 'jump' ? 'up' : raw;
      const press = (e) => {
        e.preventDefault();
        this.enableTouchMode();
        this._gesture();
        this.ts.add(action);
        this.tsPressed.add(action);
        btn.classList.add('pressed');
        try { btn.setPointerCapture(e.pointerId); } catch (_) {}
      };
      const release = (e) => {
        e.preventDefault();
        this.ts.delete(action);
        btn.classList.remove('pressed');
      };
      btn.addEventListener('pointerdown', press);
      for (const ev of ['pointerup', 'pointercancel', 'lostpointercapture']) {
        btn.addEventListener(ev, release);
      }
    });
  }

  resetPad() {
    this.pad.active = false;
    this.pad.x = 0;
    this.pad.y = 0;
    this.ts.delete('up'); this.ts.delete('down');
    this.ts.delete('left'); this.ts.delete('right');
  }

  held(action) {
    return this.kb.has(action) || this.ts.has(action);
  }

  pressed(action) {
    return this.kbPressed.has(action) || this.tsPressed.has(action);
  }

  clearPressed() {
    this.kbPressed.clear();
    this.tsPressed.clear();
  }

  releaseAll() {
    this.kb.clear();
    this.ts.clear();
    this.clearPressed();
    this.resetPad();
  }
}

