        hipY: 72, lean: 0, rot: -Math.PI * 2.4, footF: { x: 70, y: 8 }, footB: { x: -8, y: 62 },
      }),
      F(STAND, 0.62, {
        hipY: 70, lean: 0.06, rot: -Math.PI * 2.9, footF: { x: 40, y: 44 }, footB: { x: -16, y: 70 },
      }),
      F(STAND, 0.9, { rot: -Math.PI * 3, hipY: 74 }),
    ],
  }),
};

/* Hitstun / knockdown / victory poses are generated by the fighter. */
export function poseForMove(move, time) {
  const anim = move.anim;
  if (!anim || anim.length === 0) return BASE[move.poseKind] || STAND;
  if (time <= anim[0].t) return anim[0];
  if (time >= anim[anim.length - 1].t) return anim[anim.length - 1];
  for (let i = 0; i < anim.length - 1; i++) {
    const a = anim[i];
    const b = anim[i + 1];
    if (time >= a.t && time <= b.t) {
      const span = b.t - a.t || 1;
      const u = (time - a.t) / span;
      const e = u * u * (3 - 2 * u);
      return {
        hipY: a.hipY + (b.hipY - a.hipY) * e,
        lean: a.lean + (b.lean - a.lean) * e,
        tilt: a.tilt + (b.tilt - a.tilt) * e,
        rot: a.rot + (b.rot - a.rot) * e,
        offY: (a.offY || 0) + ((b.offY || 0) - (a.offY || 0)) * e,
        handF: {
          x: a.handF.x + (b.handF.x - a.handF.x) * e,
          y: a.handF.y + (b.handF.y - a.handF.y) * e,
        },
        handB: {
          x: a.handB.x + (b.handB.x - a.handB.x) * e,
          y: a.handB.y + (b.handB.y - a.handB.y) * e,
        },
        footF: {
          x: a.footF.x + (b.footF.x - a.footF.x) * e,
          y: a.footF.y + (b.footF.y - a.footF.y) * e,
        },
        footB: {
          x: a.footB.x + (b.footB.x - a.footB.x) * e,
          y: a.footB.y + (b.footB.y - a.footB.y) * e,
        },
      };
    }
  }
  return anim[anim.length - 1];
}

export const EX_MULT = { damage: 1.55, chip: 2, speed: 1.25, radius: 1.5, kb: 1.25 };

content.text:
Now fighter.js. Let's implement carefully.

Constants:
```
export const GRAVITY = 2400;
export const FLOOR_Y = 596; // renderer uses
export const STAGE_MIN = 110, STAGE_MAX = 1170;
```

Fighter:
```js
export class Fighter {
  constructor({name, tag, palette, isPlayer, difficulty}) {...}
  resetRound(x, facing)
```

Fields include `walkPhase`, `time`, `poseTime` for anim.

`update(dt, game)`:
- if state ko: handle fall physics; return
- move progression
- timers
- physics

Let's write:

```js
update(dt, game) {
  this.time += dt;
  const step = dt;
  if (this.flash > 0) this.flash -= dt;
  if (this.invuln > 0) this.invuln -= dt;
  if (this.buffer) { this.buffer.t -= dt; if (this.buffer.t <= 0) this.buffer = null; }
  if (this.comboTimer > 0) { this.comboTimer -= dt; if (this.comboTimer <= 0) this.combo = 0; }
  this.blocking = false; // recomputed

  if (this.state === 'ko') { this.updateDown(dt); return; }

  // knockdown timer
  if (this.knockdown > 0) {
    this.knockdown -= dt;
    this.vx *= Math.pow(0.02, dt);
    this.x += this.vx * dt;
    if (this.knockdown <= 0) {
      this.state = 'idle'; this.invuln = 0.35; this.y = 0; this.vy = 0; this.airborne = false;
    }
    return;
  }

  // move animation
  if (this.move) {
    const m = this.move;
    m.time += dt;
    if (m.projectile && !m.spawned && m.time >= m.startup) {
      m.spawned = true;
      game.spawnProjectile(this, m);
    }
    if (m.liftY && !m.lifted && m.time >= m.startup) {
      m.lifted = true;
      this.vy = m.liftY;
      this.airborne = true;
      this.y = Math.max(this.y, 1);
      this.vx = this.facing * (m.vx || 0);
    }
    if (m.vx && !m.projectile) {
      // apply forward slide during active
      if (m.time > m.startup && m.time < m.startup + m.active) this.vx = this.facing * m.vx;
      else this.vx *= Math.pow(0.05, dt);
    }
    if (m.time >= m.total) this.endMove(game);
  }

  if (this.hitstun > 0) {
    this.hitstun -= dt;
    this.blockstun = 0;
    if (this.hitstun <= 0 && !this.airborne) {
      this.state = 'idle';
    }
  } else if (this.blockstun > 0) {
    this.blockstun -= dt;
  }

  this.physics(dt, game);
}
```

But hitstun and move can't overlap (move cleared on hit). Actually if a fighter is hit during a move, we cancel the move. So they're exclusive.

physics:
```js
physics(dt, game) {
  const gravityOn = this.airborne || this.y > 0;
  if (gravityOn) {
    this.vy -= GRAVITY * dt;
    this.y += this.vy * dt;
    if (this.y <= 0) {
      this.y = 0;
      if (this.vy < -200) { game.fx.dust(this.x, 0, 0.8); game.sfx.land(); }
      this.vy = 0;
      this.airborne = false;
      this.airAttackUsed = false;
      if (this.move && this.move.id === 'spin') this.endMove(game);
      if (this.hitstun > 0) {
        // knocked down on landing
        if (this.hitstun > 0.15) this.startKnockdown(game); 
      } else if (this.move && this.move.time > this.move.startup + this.move.active) {
        this.endMove(game);
      } else if (!this.move) {
        this.state = 'idle';
      }
      game.fx.dust(this.x, 0, 0.5);
      this.vx = 0;
    }
  } else {
    this.vx *= Math.pow(this.state === 'hitstun' ? 0.001 : 0.02, dt);
  }
  this.x += this.vx * dt;
  // stage bounds
  this.x = clamp(this.x, STAGE_MIN, STAGE_MAX);
}
```
Careful: `vx * pow(0.001,dt)` at 60fps ≈ 0.89 per frame. Fine.

But applying vx decay while walking would zero walk speed. Walking sets vx every frame in control, then update runs physics after control → decays ~11% before moving. Slight slowdown, acceptable, but better set locomotion via direct delta? It's fine: 230*0.89 ≈ 205 effective. But after control sets vx=230, physics moves x by 3.8*0.89? Actually x += vx*dt before decay? In code above decay then apply. Let me apply decay only when not `groundedControl` flag. Add `this.movingControlled` set in control; if true, skip decay.

Simpler: in control, set `this.vx` and mark `this.controlVx = true`; in physics, if controlVx, don't decay; reset controlVx=false after. Add.

Land while in hitstun → knockdown. Let's set hitstun large enough for launch and use `this.pendingKnockdown` when launched. On land, if this.wasLaunched or hitstun>0: knockdown.

Knockdown: set state 'knockdown', this.knockdown=0.85, this.move=null, this.airborne=false, y=0. Pose lying. During knockdown, x slides with vx.

KO: state 'ko', knockdown indefinite; body lying. After round ends we reset.

`endMove(game)`:
```js
const m = this.move; this.move = null;
if (this.state !== 'ko') this.state = 'idle';
this.crouching = false;
```
But if airborne, state 'jump'. Let's set state = this.airborne ? 'jump' : 'idle'.

`startMove(id, game)`:
```js
const d = MOVES[id];
if (!d) return false;
if (!this.canAct()) return false;
let ex = false;
if (d.special && this.meter >= 100 && id !== ... ) { ex = true; this.meter = 0; game.sfx.superReady? } 
```
EX trigger: auto when meter full. But we want meter to be visible and consumed. Yes auto-EX.

```js
const m = { ...d, ex, time: 0, hits: 0, lastHitT: -1, spawned: false, lifted: false };
if (d.projectile && ex) {
  m.projectile = { ...d.projectile, speed: d.projectile.speed*1.25, radius: d.projectile.radius*1.45, damage: Math.round(d.projectile.damage*1.55), chip: d.projectile.chip*2, kb: d.projectile.kb*1.2, ex: true };
}
if (d.damage && ex) m.damage = Math.round(d.damage*1.55);
if (d.chip) m.chip = Math.round(d.chip*2);
if (d.invuln) this.invuln = d.invuln;
this.move = m;
this.state = 'attack';
this.airborne stays? if grounded, stay.
this.vx = d.vx && d.projectile ? this.facing*40 : this.vx;
if (id==='spin' || id==='dp') this.airAttackUsed = false;
game.sfx[d.sfx]?.()
```
For 'fireball' sound at startup maybe when spawned. Play whoosh at start and fireball at spawn for both? Use fireball sfx on spawn only. Add game event in spawn. Keep startMove sound for dp/spin, and nothing for fireball until spawn.

Projectile limit: game.spawnProjectile returns false if owner already has one; the move still happens (whiff). To prevent spamming, fighter can check `game` before starting fireball: game.projectiles.some(p=>p.owner===this && !p.dead). If so, maybe still allow but no spawn. Fine; classic SF allows only one.

Grounded special restriction: fireball/dp/spin only when !airborne. tryAttack handles.

`canAct()`:
```js
return this.state !== 'ko' && this.state !== 'knockdown' && this.state !== 'win'
  && !this.move && this.hitstun <= 0 && this.blockstun <= 0;
```
`canAttack()` same + (airborne ? !airAttackUsed : true).

Jump:
```js
jump(dir, game) {
  this.vy = 900;
  this.airborne = true;
  this.y = Math.max(this.y, 1);
  this.vx = dir * 210;  // if dir==0, small hop
  this.state = 'jump';
  this.airAttackUsed = false;
  this.crouching = false;
  game.sfx.jump(); game.fx.dust(...);
}
```
Note: jump duration = 2*900/2400 = 0.75s. Good height = 900²/(2*2400) = 168.

Control:
```js
control(ctrl, dt, game) {
  this.ctrlDir = ctrl.dir || 0;
  this.ctrlCrouch = !!ctrl.crouch;
  this.facingLock? 
  if (ctrl.action) this.buffer = { action: ctrl.action, t: 0.18 };
  if (this.state === 'ko' || this.state === 'knockdown' || this.state === 'win') return;
  if (!this.canAct()) return;
  if (!this.airborne) {
    this.facing = ctrl.oppX >= this.x ? 1 : -1; // always face opponent
  }
  if (ctrl.jump && !this.airborne) { this.jump(ctrl.dir, game); return; }
  // buffered action
  if (this.buffer) {
    const a = this.buffer.action;
    this.buffer = null;
    if (this.tryAttack(a, ctrl, game)) return;
  }
  if (!this.airborne) {
    if (ctrl.crouch) { this.crouching = true; this.vx = 0; this.state='crouch'; this.controlVx = true; }
    else {
      this.crouching = false;
      if (ctrl.dir !== 0) {
        const forward = ctrl.dir === this.facing;
        this.vx = ctrl.dir * (forward ? 235 : 180);
        this.state = 'walk';
      } else {
        this.vx = 0; this.state = 'idle';
      }
      this.controlVx = true;
    }
    this.walkPhase += dt * (this.state === 'walk' ? 11 : 0);
  } else {
    this.crouching = false;
    if (ctrl.dir !== 0) {
      this.vx = clamp(this.vx + ctrl.dir * 520 * dt, -270, 270);
    }
  }
}
```

Blocking flag: `isBlocking(ctrl)`: grounded, canAct or in blockstun, and ctrl.dir === -facing. Note during walk back, ctrl.dir is away, so yes. During blockstun, still holding away. Game checks `this.blockHeld`. Set `this.blockHeld = ctrl.dir === -facing && !this.airborne` each frame even if can't act (so holding back during blockstun continues). Compute in game.

Facing: always face opponent when grounded and not in move? During move facing locked. Since control returns early if !canAct, facing updates only when actionable. Good.

tryAttack(a, ctrl, game):
```js
if (this.airborne) {
  if (this.airAttackUsed) return false;
  const id = a === 'kick' ? 'airKick' : 'airPunch';
  this.airAttackUsed = true;
  return this.startMove(id, game);
}
if (a === 'fire' || a === 'dp' || a === 'spin') {
  return this.startMove(a, game);
}
if (ctrl.crouch || this.crouching) {
  return this.startMove(a === 'kick' ? 'sweep' : 'crouchJab', game);
}
if (a === 'lp') return this.startMove('jab', game);
if (a === 'hp') return this.startMove('heavy', game);
if (a === 'kick') return this.startMove('kick', game);
return false;
```

Note: buffer might hold 'lp' while airborne; handled.

Get pose:
```js
getPose() {
  const t = this.time;
  if (this.state === 'ko') return koPose;
  if (this.state === 'knockdown') return knockdownPose;
  if (this.move) return poseForMove(this.move, this.move.time);
  if (this.hitstun > 0) return hitPose(this.hitstun);
  if (this.state === 'win') return winPose(t);
  if (this.airborne) return airPose(t, this.vy);
  if (this.crouching) return this.blockHeld ? CROUCH_GUARD : crouchPose(t);
