```js
if (this.state !== 'fight') return;
this.state='roundEnd';
this.roundEndT=3.0;
this.winPoseT=0.9;
const p=this.player,c=this.cpu;
let w = winner || null;
if (!w) {
  if (reason==='timeout') { if (p.hp>c.hp) w=p; else if (c.hp>p.hp) w=c; }
}
this.roundWinner = w;
