if (reason==='ko') {
  this.announceNow('K.O.', {style:'red', size:180, y:300, dur:2.0, sub: w ? `${w.name} WINS THE ROUND` : 'DOUBLE K.O.'});
  this.flash = Math.max(this.flash, 0.55);
