import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.js';
import { readFileSync, mkdirSync } from 'node:fs';

const cfg = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
const out = '/tmp/neon-shots';
mkdirSync(out, { recursive: true });

const browser = await chromium.launch({ ...cfg.browser.launchOptions, timeout: 30000 });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(1400);
await page.screenshot({ path: `${out}/01-title.jpg`, type: 'jpeg', quality: 78 });

await page.click('#btn-start');
await page.waitForTimeout(2200);
await page.screenshot({ path: `${out}/02-fight.jpg`, type: 'jpeg', quality: 78 });

// state dump
const state1 = await page.evaluate(() => {
  const g = window.__neonFist.game;
  return { state: g.state, timer: g.timer, p: { x: g.player.x, hp: g.player.hp }, c: { x: g.cpu.x, hp: g.cpu.hp } };
});
console.log('STATE1', JSON.stringify(state1));

// walk forward and jab
await page.keyboard.down('KeyD');
await page.waitForTimeout(500);
await page.keyboard.up('KeyD');
await page.keyboard.press('KeyJ');
await page.waitForTimeout(120);
await page.screenshot({ path: `${out}/03-jab.jpg`, type: 'jpeg', quality: 78 });

// walk closer and fireball
await page.keyboard.down('KeyD');
await page.waitForTimeout(450);
await page.keyboard.up('KeyD');
await page.keyboard.press('KeyU');
await page.waitForTimeout(260);
await page.screenshot({ path: `${out}/04-fireball.jpg`, type: 'jpeg', quality: 78 });

const state2 = await page.evaluate(() => {
  const g = window.__neonFist.game;
  return { state: g.state, projectiles: g.projectiles.length, pMove: g.player.move?.moveId || null, cHp: g.cpu.hp };
});
console.log('STATE2', JSON.stringify(state2));

await page.waitForTimeout(2500);
await page.screenshot({ path: `${out}/05-later.jpg`, type: 'jpeg', quality: 78 });
const state3 = await page.evaluate(() => {
  const g = window.__neonFist.game;
  return { state: g.state, timer: g.timer, pHp: g.player.hp, cHp: g.cpu.hp, pMeter: g.player.meter, cMeter: g.cpu.meter, wins: [g.player.wins, g.cpu.wins] };
});
console.log('STATE3', JSON.stringify(state3));

// force a special pose for screenshot: dp
await page.evaluate(() => {
  const g = window.__neonFist.game;
  g.player.x = 560; g.cpu.x = 700;
  g.player.meter = 100;
