});
await page.waitForTimeout(180);
await page.screenshot({ path: `${out}/06-dp.jpg`, type: 'jpeg', quality: 78 });

// mobile
const mob = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
mob.on('pageerror', (e) => errors.push('MOBILE PAGEERROR: ' + e.message));
await mob.goto('http://localhost:3002', { waitUntil: 'load' });
await mob.waitForTimeout(1200);
await mob.screenshot({ path: `${out}/07-mobile-title.jpg`, type: 'jpeg', quality: 78 });
await mob.tap('#btn-start');
await mob.waitForTimeout(2400);
await mob.screenshot({ path: `${out}/08-mobile-fight.jpg`, type: 'jpeg', quality: 78 });

console.log('ERRORS', JSON.stringify(errors, null, 2));
await browser.close();

