86:     this.projectiles.length = 0;
87:     this.timer = ROUND_TIME;
88:     this.introT = 1.75;
89:     this.state = 'intro';
90:     this.showHUD = true;
91:     this.paused = false;
92:     this.roundEndT = 0;
93:     this.roundWinner = null;
94:     this.announceNow(`ROUND ${this.round}`, {
95:       dur: 1.25, size: 104, style: 'gold',
96:       sub: this.round === 3 ? 'FINAL ROUND' : '',
97:     });
