103:   announceNow(text, opts = {}) {
104:     this.announce = {
105:       text,
106:       sub: opts.sub || '',
107:       style: opts.style || 'gold',
108:       size: opts.size || 110,
109:       life: opts.dur || 1.2,
110:       dur: opts.dur || 1.2,
111:       y: opts.y || 300,
112:       glow: opts.glow,
113:     };
114:   }
