131: 
132:   /* ============================================================
133:      MAIN STEP
134:      ============================================================ */
135:   step(dt, input) {
136:     if (this.paused) return;
137:     this.clock += dt;
138: 
139:     if (this.announce) {
140:       this.announce.life -= dt;
141:       if (this.announce.life <= 0) this.announce = null;
142:     }
143:     this.shake = Math.max(0, this.shake - (this.shake * 9 + 0.4) * dt);
144:     this.flash = Math.max(0, this.flash - dt * 2.6);
145:     for (const f of [this.player, this.cpu]) {
146:       if (f.trailHp > f.hp) {
147:         f.trailDelay = Math.max(0, (f.trailDelay || 0) - dt);
148:         if (f.trailDelay <= 0) f.trailHp = Math.max(f.hp, f.trailHp - 480 * dt);
149:       } else {
150:         f.trailHp = f.hp;
151:       }
152:     }
153:     this.fx.update(dt);
154: 
155:     if (this.hitstop > 0) {
156:       this.hitstop -= dt;
157:       return;
158:     }
159: 
160:     if (this.state === 'title') {
161:       this.player.update(dt, this);
162:       this.cpu.update(dt, this);
163:       return;
164:     }
165: 
166:     if (this.state === 'intro') {
167:       this.introT -= dt;
168:       this.neutralControl(this.player, this.cpu, dt);
169:       this.neutralControl(this.cpu, this.player, dt);
170:       this.player.update(dt, this);
171:       this.cpu.update(dt, this);
172:       if (this.introT <= 0) {
173:         this.state = 'fight';
174:         this.announceNow('FIGHT!', { dur: 0.9, size: 122, style: 'gold', y: 300 });
175:         this.sfx.fight();
176:       }
177:       return;
178:     }
179: 
180:     if (this.state === 'fight') {
181:       this.timer -= dt;
182:       if (this.timer <= 0) {
183:         this.timer = 0;
184:         this.endRound('timeout');
185:         return;
186:       }
187:       this.applyPlayerControl(input, dt);
188:       this.cpuAI.update(dt, this);
189:       this.player.update(dt, this);
190:       this.cpu.update(dt, this);
191:       this.resolveBodies();
192:       this.checkAttack(this.player, this.cpu);
193:       this.checkAttack(this.cpu, this.player);
194:       this.updateProjectiles(dt);
195:       return;
196:     }
197: 
198:     if (this.state === 'roundEnd' || this.state === 'matchEnd') {
199:       this.neutralControl(this.player, this.cpu, dt);
200:       this.neutralControl(this.cpu, this.player, dt);
201:       this.player.update(dt, this);
202:       this.cpu.update(dt, this);
203:       this.updateProjectiles(dt);
204:       if (this.state === 'roundEnd') {
205:         this.winPoseT -= dt;
206:         if (this.winPoseT <= 0 && this.roundWinner && this.roundWinner.state !== 'ko') {
207:           this.roundWinner.state = 'win';
208:           this.roundWinner.move = null;
209:           this.roundWinner.crouching = false;
210:         }
211:         this.roundEndT -= dt;
212:         if (this.roundEndT <= 0) this.afterRound();
213:       }
214:       return;
215:     }
216:   }
217: 
218:   neutralControl(f, opp, dt) {
219:     f.control({ dir: 0, jump: false, crouch: false, action: null, oppX: opp.x }, dt, this);
220:   }
221: 
222:   applyPlayerControl(input, dt) {
223:     const p = this.player;
224:     const c = this.cpu;
225:     if (p.state === 'ko' || p.state === 'win') return;
226:     const dir = (input.held('right') ? 1 : 0) - (input.held('left') ? 1 : 0);
227:     const crouch = input.held('down');
228:     const jump = input.pressed('up');
229:     let action = null;
230:     if (input.pressed('fire')) action = 'fire';
231:     else if (input.pressed('dp')) action = 'dp';
232:     else if (input.pressed('spin')) action = 'spin';
233:     else if (input.pressed('lp')) action = 'lp';
234:     else if (input.pressed('hp')) action = 'hp';
235:     else if (input.pressed('kick')) action = 'kick';
236: 
237:     this.trackDirection(dir, crouch, p);
238:     if (action && (action === 'lp' || action === 'hp' || action === 'kick')) {
239:       const motion = this.detectMotion(action, p);
240:       if (motion) action = motion;
241:     }
242:     p.control({ dir, jump, crouch, action, oppX: c.x }, dt, this);
243:   }
244: 
245:   trackDirection(dir, crouch, p) {
246:     const rel = dir === 0 ? 0 : dir === p.facing ? 1 : -1;
247:     let tok = 'n';
248:     if (crouch && rel === 1) tok = 'df';
249:     else if (crouch && rel === -1) tok = 'db';
250:     else if (crouch) tok = 'd';
251:     else if (rel === 1) tok = 'f';
252:     else if (rel === -1) tok = 'b';
253:     if (tok !== this.lastDirToken) {
254:       this.lastDirToken = tok;
255:       this.dirHistory.push({ tok, t: this.clock });
256:       if (this.dirHistory.length > 24) this.dirHistory.shift();
257:     }
258:   }
259: 
260:   detectMotion(action, p) {
261:     const recent = this.dirHistory.filter((h) => this.clock - h.t < 0.42);
262:     const toks = recent.map((h) => h.tok);
263:     if (toks.length < 2) return null;
264:     const last = toks[toks.length - 1];
265:     if ((action === 'lp' || action === 'hp')) {
266:       if (last === 'f') {
267:         const fi = toks.lastIndexOf('f');
268:         if (toks.slice(0, fi).some((t) => t === 'd' || t === 'df')) return 'fire';
269:       }
270:       // dragon punch: forward, down, down-forward
271:       const s = toks.join(' ');
272:       if (/(^| )f( |$).*d.*df/.test(s)) return 'dp';
273:       if (last === 'df' && toks.slice(0, -1).some((t) => t === 'f' || t === 'd')) return 'dp';
274:     }
275:     if (action === 'kick' && last === 'b') {
276:       const bi = toks.lastIndexOf('b');
277:       if (toks.slice(0, bi).some((t) => t === 'd' || t === 'db')) return 'spin';
278:     }
279:     return null;
280:   }
281: 
282:   resolveBodies() {
283:     const a = this.player;
284:     const b = this.cpu;
285:     if (a.state === 'ko' || b.state === 'ko') return;
286:     if (a.state === 'knockdown' || b.state === 'knockdown') return;
287:     const dx = b.x - a.x;
288:     const dist = Math.abs(dx);
289:     const min = 62;
290:     if (dist < min) {
291:       const push = (min - dist) / 2;
292:       const s = dx >= 0 ? 1 : -1;
293:       a.x = clamp(a.x - s * push, STAGE_MIN, STAGE_MAX);
294:       b.x = clamp(b.x + s * push, STAGE_MIN, STAGE_MAX);
295:     }
296:     a.x = clamp(a.x, STAGE_MIN, STAGE_MAX);
297:     b.x = clamp(b.x, STAGE_MIN, STAGE_MAX);
298:   }
299: 
300:   /* ============================================================
301:      ATTACKS
302:      ============================================================ */
303:   checkAttack(att, def) {
304:     if (this.state !== 'fight') return;
305:     const m = att.move;
306:     if (!m || !m.hitbox) return;
307:     if (m.hits >= m.maxHits) return;
308:     const activeStart = m.startup;
309:     const activeEnd = m.startup + m.active;
310:     if (m.time < activeStart || m.time > activeEnd) return;
311:     if (m.lastHitT >= 0 && m.time - m.lastHitT < m.hitInterval) return;
312:     if (def.state === 'ko' || def.state === 'knockdown' || def.invuln > 0) return;
313:     const hb = att.getHitbox(m);
314:     const hurt = def.getHurtbox();
315:     if (!rectsOverlap(hb, hurt)) return;
316:     m.hits++;
317:     m.lastHitT = m.time;
318:     const hx = clamp((hb.x + hb.w * 0.5 + def.x) * 0.5, def.x - 50, def.x + 50);
319:     const hy = FLOOR_Y - (hb.y + hb.h * 0.55 + def.y * 0.5);
320:     this.applyStrike(att, def, m, hx, hy);
321:   }
322: 
323:   applyStrike(att, def, data, hx, hy) {
324:     if (this.state !== 'fight') return;
325:     if (def.state === 'ko' || def.state === 'knockdown') return;
326:     if (def.invuln > 0) return;
327: 
328:     const facing = data.facingDir || att.facing;
329:     const blocked =
330:       def.isBlocking() &&
331:       !(data.low && !def.crouching) &&
332:       !(data.overhead && def.crouching);
333: 
334:     const meterGain = data.meterGain || 6;
335: 
336:     if (blocked) {
337:       const chip = data.chip || 0;
338:       def.hp = Math.max(0, def.hp - chip);
339:       def.blockstun = Math.max(def.blockstun, data.blockstun || 0.16);
340:       def.vx = facing * (data.kb || 140) * 0.4;
341:       att.vx = -facing * 40;
342:       att.meter = clamp(att.meter + meterGain * 0.55, 0, 100);
343:       def.meter = clamp(def.meter + meterGain * 0.8, 0, 100);
344:       def.flash = 0.05;
345:       this.fx.blockSpark(hx, hy);
346:       this.sfx.block();
347:       this.hitstop = Math.max(this.hitstop, 0.045);
348:       this.shake = Math.max(this.shake, 2.4);
349:       if (chip > 0) {
350:         def.trailDelay = 0.32;
351:         if (def.hp <= 0) this.ko(def, att);
352:       }
353:       this.watchMeter();
354:       return;
355:     }
356: 
357:     const dmg = Math.max(1, Math.round(data.damage || 0));
358:     def.hp = Math.max(0, def.hp - dmg);
359:     def.trailDelay = 0.36;
360:     def.flash = 0.14;
361:     def.move = null;
362:     def.blockstun = 0;
363:     def.crouching = false;
364:     def.state = 'hitstun';
365:     def.hitstun = data.hitstun || 0.26;
366:     def.vx = facing * (data.kb || 150);
367:     if (data.launch) {
368:       def.airborne = true;
369:       def.vy = 660;
370:       def.y = Math.max(def.y, 3);
371:       def.hitstun = 1.4;
372:     }
373:     const finalKnock = data.knockdown && (!data.maxHits || data.hits >= data.maxHits);
374:     if (finalKnock && !data.launch) {
375:       def.state = 'knockdown';
376:       def.knockdown = def.hp <= 0 ? 999 : 0.95;
377:       def.hitstun = 0;
378:       def.vx = facing * (data.kb || 150) * 0.85;
379:       this.fx.dust(def.x, 0, 1);
380:     }
381: 
382:     att.meter = clamp(att.meter + meterGain, 0, 100);
383:     def.meter = clamp(def.meter + meterGain * 0.75, 0, 100);
384:     att.combo++;
385:     att.comboTimer = 1.15;
386:     att.stats.damageDealt += dmg;
387:     att.stats.maxCombo = Math.max(att.stats.maxCombo, att.combo);
388:     def.combo = 0;
389:     def.comboTimer = 0;
390: 
391:     const power = clamp(dmg / 130, 0.25, 2.2);
392:     this.fx.hitSpark(hx, hy, power, att.pal.energy2, att.pal.energy);
393:     if (data.launch) this.fx.shock(hx, hy, 1.2, att.pal.energy2);
394:     this.shake = Math.max(this.shake, (data.shake || 5) * 1.1);
395:     this.hitstop = Math.max(this.hitstop, data.hitstop || 0.06);
396:     this.sfx.hit(power);
397:     this.watchMeter();
398: 
399:     if (def.hp <= 0) this.ko(def, att);
400:   }
401: 
402:   ko(def, att) {
403:     if (def.state === 'ko') return;
404:     this.hitstop = 0.32;
405:     this.flash = 0.72;
406:     this.flashColor = '#fff3dc';
407:     this.shake = Math.max(this.shake, 22);
408:     this.fx.koBurst(def.x, FLOOR_Y - def.y - 92);
409:     def.startKO(this);
410:     this.sfx.ko();
411:     this.endRound('ko', att);
412:   }
413: 
414:   watchMeter() {
415:     for (const f of [this.player, this.cpu]) {
416:       if (f.meter >= 100 && !f._wasFull) {
417:         f._wasFull = true;
418:         this.sfx.superReady();
419:       } else if (f.meter < 100) {
420:         f._wasFull = false;
421:       }
422:     }
423:   }
424: 
425:   onEx(f) {
426:     this.flash = Math.max(this.flash, 0.22);
427:     this.flashColor = f.pal.energy;
428:     this.shake = Math.max(this.shake, 8);
429:     this.hitstop = Math.max(this.hitstop, 0.09);
430:     this.fx.shock(f.x, FLOOR_Y - f.y - 90, 1.4, f.pal.energy2);
431:     this.sfx.superReady();
432:   }
433: 
434:   /* ============================================================
435:      PROJECTILES
436:      ============================================================ */
437:   spawnProjectile(f, m) {
438:     if (this.projectiles.some((p) => p.owner === f && !p.dead)) return;
439:     const pd = m.projectile;
440:     this.projectiles.push({
441:       owner: f,
442:       x: f.x + f.facing * 62,
443:       y: pd.height,
444:       vx: f.facing * pd.speed,
445:       radius: pd.radius,
446:       damage: pd.damage,
447:       chip: pd.chip,
448:       hitstun: pd.hitstun,
449:       blockstun: pd.blockstun,
450:       kb: pd.kb,
451:       shake: pd.shake,
452:       ex: m.ex,
453:       pal: f.pal,
454:       facingDir: f.facing,
455:       life: 2.6,
456:       trailT: 0,
457:       dead: false,
458:     });
459:     this.sfx.fireball();
460:     this.shake = Math.max(this.shake, 3);
461:   }
462: 
463:   updateProjectiles(dt) {
464:     const ps = this.projectiles;
465:     for (const p of ps) {
466:       if (p.dead) continue;
467:       p.x += p.vx * dt;
468:       p.life -= dt;
469:       p.trailT -= dt;
470:       if (p.trailT <= 0) {
471:         p.trailT = 0.018;
472:         this.fx.projectileTrail(
473:           p.x - Math.sign(p.vx) * p.radius * 0.5,
474:           FLOOR_Y - p.y,
475:           p.pal.energy,
476:           (p.radius / 23) * 1,
477:           p.ex
478:         );
479:       }
480:       if (p.x < -80 || p.x > 1360 || p.life <= 0) p.dead = true;
481:     }
482:     // projectile vs projectile
483:     for (let i = 0; i < ps.length; i++) {
484:       for (let j = i + 1; j < ps.length; j++) {
485:         const a = ps[i];
486:         const b = ps[j];
487:         if (a.dead || b.dead || a.owner === b.owner) continue;
488:         if (Math.abs(a.x - b.x) < (a.radius + b.radius) * 0.9 && Math.abs(a.y - b.y) < a.radius + b.radius) {
489:           a.dead = true;
490:           b.dead = true;
491:           const mx = (a.x + b.x) / 2;
492:           this.fx.hitSpark(mx, FLOOR_Y - (a.y + b.y) / 2, 1.4, '#fff4d0', '#ffcf7a');
493:           this.fx.shock(mx, FLOOR_Y - (a.y + b.y) / 2, 1.2);
494:           this.sfx.block();
495:           this.shake = Math.max(this.shake, 6);
496:         }
497:       }
498:     }
499:     // projectile vs fighters
500:     for (const p of ps) {
501:       if (p.dead || this.state !== 'fight') continue;
502:       const target = p.owner === this.player ? this.cpu : this.player;
503:       if (!target || target.state === 'ko' || target.state === 'knockdown') continue;
504:       if (target.invuln > 0) continue;
505:       const hurt = target.getHurtbox();
506:       const nx = clamp(p.x, hurt.x, hurt.x + hurt.w);
507:       const ny = clamp(p.y, hurt.y, hurt.y + hurt.h);
508:       const ddx = p.x - nx;
509:       const ddy = p.y - ny;
510:       if (ddx * ddx + ddy * ddy > p.radius * p.radius) continue;
511:       const blocked = target.isBlocking() && !target.airborne;
512:       p.dead = true;
513:       if (blocked) {
514:         target.hp = Math.max(0, target.hp - p.chip);
515:         target.trailDelay = 0.3;
516:         target.blockstun = Math.max(target.blockstun, p.blockstun);
517:         target.vx = p.facingDir * p.kb * 0.5;
518:         p.owner.meter = clamp(p.owner.meter + 4, 0, 100);
519:         target.meter = clamp(target.meter + 6, 0, 100);
520:         this.fx.blockSpark(p.x, FLOOR_Y - p.y);
521:         this.sfx.block();
522:         this.shake = Math.max(this.shake, 3);
523:         if (target.hp <= 0) this.ko(target, p.owner);
524:         this.watchMeter();
525:       } else {
526:         const data = {
527:           damage: p.damage,
528:           chip: p.chip,
529:           hitstun: p.hitstun,
530:           blockstun: p.blockstun,
531:           kb: p.kb,
532:           shake: p.shake,
533:           hitstop: 0.08,
534:           knockdown: p.ex,
535:           maxHits: 1,
536:           hits: 1,
537:           launch: false,
538:           meterGain: 8,
539:           facingDir: p.facingDir,
540:         };
541:         this.applyStrike(p.owner, target, data, p.x, FLOOR_Y - p.y);
542:       }
543:     }
544:     this.projectiles = ps.filter((p) => !p.dead);
545:   }
546: 
547:   /* ============================================================
548:      ROUND FLOW
549:      ============================================================ */
550:   endRound(reason, winner = null) {
551:     if (this.state !== 'fight') return;
552:     this.state = 'roundEnd';
553:     this.roundEndT = 3.0;
554:     this.winPoseT = 0.9;
555:     const p = this.player;
556:     const c = this.cpu;
557:     let w = winner;
558:     if (!w && reason === 'timeout') {
559:       if (p.hp > c.hp) w = p;
560:       else if (c.hp > p.hp) w = c;
561:     }
562:     this.roundWinner = w;
563:     if (w) w.wins += 1;
564: 
565:     if (reason === 'ko') {
566:       this.announceNow('K.O.', {
567:         dur: 2.0, size: 178, style: 'red', y: 296,
568:         sub: w ? `${w.name} WINS THE ROUND` : 'DOUBLE K.O.',
569:       });
570:       this.flash = Math.max(this.flash, 0.5);
571:       this.shake = Math.max(this.shake, 12);
572:     } else {
573:       const perfect = w && w.hp >= w.maxHp;
574:       this.announceNow(w ? 'TIME UP' : 'DRAW', {
575:         dur: 1.8, size: 118, style: 'cyan', y: 296,
576:         sub: w ? (perfect ? 'PERFECT!' : `${w.name} WINS THE ROUND`) : 'NO POINTS AWARDED',
577:       });
578:       this.sfx.roundStart();
579:     }
580:   }
581: 
582:   afterRound() {
583:     if (this.roundWinner && this.roundWinner.wins >= ROUNDS_TO_WIN) {
584:       this.state = 'matchEnd';
585:       this.matchWinner = this.roundWinner;
586:       const loser = this.roundWinner === this.player ? this.cpu : this.player;
587:       this.roundWinner.state = 'win';
