const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const fs = require('fs');
const OUT = '/tmp/neon-shots';
fs.mkdirSync(OUT, { recursive: true });

const logs = [];
const errors = [];
function check(name, ok, extra = '') {
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${extra ? ' — ' + extra : ''}`);
  if (!ok) process.exitCode = 1;
}

(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium' });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); logs.push(`${m.type()}: ${m.text()}`); });
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(700);

  check('title screen visible', await page.locator('#screen-title').isVisible());
  check('canvas rendered size', await page.evaluate(() => {
    const c = document.querySelector('#game'); return c.width > 0 && c.height > 0 && c.getBoundingClientRect().width > 900;
  }));
  await page.screenshot({ path: `${OUT}/20-title.jpg`, type: 'jpeg', quality: 82 });

  // Difficulty selection
  await page.click('#difficulty button[data-diff="hard"]');
  check('difficulty hard selected', (await page.evaluate(() => window.__neonFist.game.difficulty)) === 'hard');

  // Start
  await page.click('#btn-start');
  await page.waitForTimeout(250);
  const started = await page.evaluate(() => ({
    state: window.__neonFist.game.state, hud: window.__neonFist.game.showHUD,
    playing: document.body.classList.contains('playing'), screenHidden: document.querySelector('#screen-title').classList.contains('hidden')
  }));
  check('match starts in intro', started.state === 'intro', JSON.stringify(started));
  check('title overlay hidden', started.screenHidden && started.playing);
  await page.waitForTimeout(1700);
  check('intro transitions to fight', (await page.evaluate(() => window.__neonFist.game.state)) === 'fight');
  await page.screenshot({ path: `${OUT}/21-fight.jpg`, type: 'jpeg', quality: 82 });

  // Movement and block
  const x0 = await page.evaluate(() => window.__neonFist.game.player.x);
  await page.keyboard.down('KeyD'); await page.waitForTimeout(420); await page.keyboard.up('KeyD');
  const x1 = await page.evaluate(() => window.__neonFist.game.player.x);
  check('walk forward moves player', x1 > x0 + 20, `${x0.toFixed(1)} -> ${x1.toFixed(1)}`);
  await page.keyboard.down('KeyA'); await page.waitForTimeout(140);
  const blocking = await page.evaluate(() => window.__neonFist.game.player.isBlocking());
  await page.keyboard.up('KeyA');
  check('holding back blocks', blocking === true);

  // Jump
  await page.keyboard.press('KeyW'); await page.waitForTimeout(180);
  const jumpY = await page.evaluate(() => window.__neonFist.game.player.y);
  check('jump leaves ground', jumpY > 20, `y=${jumpY.toFixed(1)}`);
  await page.waitForTimeout(900);

  // Normals
  for (const [key, id] of [['KeyJ', 'jab'], ['KeyK', 'heavy'], ['KeyL', 'kick']]) {
    await page.keyboard.press(key); await page.waitForTimeout(60);
    const mid = await page.evaluate(() => ({ id: window.__neonFist.game.player.move?.moveId, time: window.__neonFist.game.player.move?.time }));
    check(`${id} starts`, mid.id === id, JSON.stringify(mid));
    await page.waitForTimeout(700);
  }

  // Specials
  for (const [key, id] of [['KeyU', 'fireball'], ['KeyI', 'dp'], ['KeyO', 'spin']]) {
    await page.evaluate(() => { const g = window.__neonFist.game; g.player.x = 500; g.cpu.x = 700; g.player.meter = 0; });
    await page.keyboard.press(key); await page.waitForTimeout(90);
    const mid = await page.evaluate(() => ({ id: window.__neonFist.game.player.move?.moveId, state: window.__neonFist.game.player.move?.state, ex: window.__neonFist.game.player.move?.ex }));
    check(`${id} starts`, mid.id === id, JSON.stringify(mid));
    if (id === 'fireball') {
      await page.waitForTimeout(220);
      check('fireball spawns projectile', (await page.evaluate(() => window.__neonFist.game.projectiles.length)) > 0);
      await page.screenshot({ path: `${OUT}/22-fireball.jpg`, type: 'jpeg', quality: 82 });
    } else {
      await page.waitForTimeout(240);
      await page.screenshot({ path: `${OUT}/23-${id}.jpg`, type: 'jpeg', quality: 82 });
    }
    await page.waitForTimeout(950);
  }

  // EX special
  await page.evaluate(() => { const g = window.__neonFist.game; g.player.meter = 100; g.player.x = 500; g.cpu.x = 800; g.projectiles = []; });
  await page.keyboard.press('KeyU'); await page.waitForTimeout(120);
  const ex = await page.evaluate(() => ({ ex: window.__neonFist.game.player.move?.ex, meter: window.__neonFist.game.player.meter }));
  check('EX fireball activates and consumes meter', ex.ex === true && ex.meter < 100, JSON.stringify(ex));
  await page.waitForTimeout(250);
  await page.screenshot({ path: `${OUT}/24-ex.jpg`, type: 'jpeg', quality: 82 });

  // Pause
  await page.waitForTimeout(700);
  const beforePause = await page.evaluate(() => ({ timer: window.__neonFist.game.timer, t: window.__neonFist.game.clock }));
  await page.keyboard.press('KeyP'); await page.waitForTimeout(450);
  const pauseState = await page.evaluate(() => ({ paused: window.__neonFist.game.paused, title: document.querySelector('#screen-pause').classList.contains('hidden'), timer: window.__neonFist.game.timer, t: window.__neonFist.game.clock }));
  check('P opens pause and freezes game', pauseState.paused && !pauseState.title, JSON.stringify(pauseState));
  await page.screenshot({ path: `${OUT}/25-pause.jpg`, type: 'jpeg', quality: 82 });
  await page.keyboard.press('KeyP'); await page.waitForTimeout(250);
  check('P resumes', (await page.evaluate(() => window.__neonFist.game.paused)) === false);

  // Mute
  const mute0 = await page.evaluate(() => window.__neonFist.sfx.muted);
  await page.keyboard.press('KeyM'); await page.waitForTimeout(80);
  const muteState = await page.evaluate(() => ({ muted: window.__neonFist.sfx.muted, label: document.querySelector('#mute-chip').textContent }));
  check('M toggles mute', muteState.muted !== mute0 && muteState.label.includes(muteState.muted ? 'OFF' : 'ON'), JSON.stringify(muteState));
  await page.keyboard.press('KeyM');

  // Force KO and round transition
  await page.evaluate(() => { const g = window.__neonFist.game; g.player.x = 500; g.cpu.x = 560; g.cpu.hp = 1; g.cpu.state = 'idle'; g.cpu.invuln = 0; g.player.meter = 0; });
  await page.keyboard.press('KeyK'); await page.waitForTimeout(900);
  const ko = await page.evaluate(() => ({ state: window.__neonFist.game.state, cpu: window.__neonFist.game.cpu.state, wins: window.__neonFist.game.player.wins, round: window.__neonFist.game.round }));
  check('KO ends round', ko.state === 'roundEnd' && ko.cpu === 'ko' && ko.wins === 1, JSON.stringify(ko));
  await page.screenshot({ path: `${OUT}/26-ko.jpg`, type: 'jpeg', quality: 82 });
  await page.waitForTimeout(3400);
  const r2 = await page.evaluate(() => ({ state: window.__neonFist.game.state, round: window.__neonFist.game.round, cpuHp: window.__neonFist.game.cpu.hp, win: window.__neonFist.game.player.wins }));
  check('next round starts and health resets', r2.round === 2 && r2.state === 'intro' && r2.cpuHp === 1000, JSON.stringify(r2));

  // Force match end via direct calls to avoid 2 rounds wait
  await page.evaluate(() => { const g = window.__neonFist.game; g.state = 'fight'; g.player.wins = 1; g.cpu.hp = 1; g.player.x = 500; g.cpu.x = 560; g.cpu.state = 'idle'; g.cpu.invuln = 0; g.player.move = null; });
  await page.keyboard.press('KeyK');
  await page.waitForTimeout(5200);
  const end = await page.evaluate(() => ({ state: window.__neonFist.game.state, resultsVisible: !document.querySelector('#screen-results').classList.contains('hidden'), title: document.querySelector('#results-title').textContent }));
  check('match end shows results', end.state === 'matchEnd' && end.resultsVisible && end.title === 'YOU WIN', JSON.stringify(end));
  await page.screenshot({ path: `${OUT}/27-results.jpg`, type: 'jpeg', quality: 82 });

  // Rematch
  await page.click('#btn-rematch'); await page.waitForTimeout(300);
  const rematch = await page.evaluate(() => ({ state: window.__neonFist.game.state, round: window.__neonFist.game.round, wins: window.__neonFist.game.player.wins, resultsHidden: document.querySelector('#screen-results').classList.contains('hidden') }));
  check('rematch resets match', rematch.state === 'intro' && rematch.round === 1 && rematch.wins === 0 && rematch.resultsHidden, JSON.stringify(rematch));

  // Quit to title via pause
  await page.keyboard.press('KeyP'); await page.waitForTimeout(200);
  await page.click('#btn-quit'); await page.waitForTimeout(200);
  check('quit returns to title', await page.locator('#screen-title').isVisible());

  // Mobile viewport + touch
  const mob = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
  const mobErr = [];
  mob.on('pageerror', e => mobErr.push(e.message));
  await mob.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await mob.waitForTimeout(800);
  check('mobile title visible', await mob.locator('#screen-title').isVisible());
  check('touch layout class', await mob.evaluate(() => document.body.classList.contains('is-touch')));
  await mob.screenshot({ path: `${OUT}/28-mobile-title.jpg`, type: 'jpeg', quality: 82 });
  await mob.tap('#btn-start'); await mob.waitForTimeout(2100);
  const mobState = await mob.evaluate(() => ({ state: window.__neonFist.game.state, touch: getComputedStyle(document.querySelector('#touch')).display }));
  check('mobile fight starts with controls', mobState.state === 'fight' && mobState.touch === 'flex', JSON.stringify(mobState));
  await mob.screenshot({ path: `${OUT}/29-mobile-fight.jpg`, type: 'jpeg', quality: 82 });

  // touch attacks
  await mob.tap('[data-action="lp"]'); await mob.waitForTimeout(70);
  check('mobile jab button works', (await mob.evaluate(() => window.__neonFist.game.player.move?.moveId)) === 'jab');
  await mob.waitForTimeout(450);
  await mob.tap('[data-action="fire"]'); await mob.waitForTimeout(420);
  await mob.screenshot({ path: `${OUT}/30-mobile-special.jpg`, type: 'jpeg', quality: 82 });

  check('no desktop console errors', errors.length === 0, errors.join(' | '));
  check('no mobile page errors', mobErr.length === 0, mobErr.join(' | '));

  console.log('NODE_ERRORS', JSON.stringify({ errors, mobile: mobErr }));
  await browser.close();
})();

