const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
function check(name, ok, extra = '') { console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${extra ? ' — ' + extra : ''}`); if (!ok) process.exitCode = 1; }
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium' });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.on('pageerror', e => console.log('PAGEERROR', e.message));
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  await page.click('#difficulty button[data-diff="normal"]');
  await page.click('#btn-start');
  await page.waitForTimeout(1900);
  await page.evaluate(() => {
    const g = window.__neonFist.game;
    g.cpuAI.update = () => {};
    g.cpu.control = () => {};
    g.player.x = 500; g.cpu.x = 660; g.player.facing = 1; g.cpu.facing = -1;
    g.player.state = 'idle'; g.cpu.state = 'idle';
    g.player.hitstun = 0; g.cpu.hitstun = 0;
    g.player.blockstun = 0; g.cpu.blockstun = 0;
    g.player.move = null; g.cpu.move = null;
    g.projectiles = [];
  });

  for (const [key, id] of [['KeyJ','jab'],['KeyK','heavy'],['KeyL','kick']]) {
    await page.evaluate(() => { const g=window.__neonFist.game; g.player.state='idle'; g.player.move=null; g.player.hitstun=0; g.player.blockstun=0; g.player.airborne=false; g.player.y=0; });
    await page.keyboard.press(key); await page.waitForTimeout(48);
    const mid = await page.evaluate(() => ({id:window.__neonFist.game.player.move?.moveId, time:window.__neonFist.game.player.move?.time}));
    check(id, mid.id === id, JSON.stringify(mid));
    await page.waitForTimeout(800);
  }

  for (const [key, id] of [['KeyU','fireball'],['KeyI','dp'],['KeyO','spin']]) {
    await page.evaluate(() => { const g=window.__neonFist.game; g.player.x=500; g.cpu.x=760; g.player.facing=1; g.player.state='idle'; g.player.move=null; g.player.hitstun=0; g.player.blockstun=0; g.player.airborne=false; g.player.y=0; g.player.meter=0; g.projectiles=[]; });
    await page.keyboard.press(key); await page.waitForTimeout(60);
    const mid = await page.evaluate(() => ({id:window.__neonFist.game.player.move?.moveId, state:window.__neonFist.game.player.state}));
    check(id+' starts', mid.id === id, JSON.stringify(mid));
    if (id === 'fireball') {
      await page.waitForTimeout(260);
      check('fireball spawns projectile', (await page.evaluate(() => window.__neonFist.game.projectiles.length)) > 0);
    }
    await page.waitForTimeout(1000);
  }

  // Test hits
  await page.evaluate(() => { const g=window.__neonFist.game; g.player.x=500; g.cpu.x=620; g.player.facing=1; g.cpu.face=1; g.cpu.state='idle'; g.cpu.hp=1000; g.cpu.move=null; g.cpu.hitstun=0; g.cpu.blockHeld=false; g.cpu.invuln=0; g.cpu.airborne=false; g.cpu.y=0; g.player.state='idle'; g.player.move=null; g.player.hitstun=0; });
  await page.keyboard.press('KeyK');
  await page.waitForTimeout(250);
  const hit = await page.evaluate(() => ({hp:window.__neonFist.game.cpu.hp, state:window.__neonFist.game.cpu.state, combo:window.__neonFist.game.player.combo, meter:window.__neonFist.game.player.meter}));
  check('heavy damages CPU', hit.hp < 1000, JSON.stringify(hit));
  check('heavy builds meter', hit.meter > 0, JSON.stringify(hit));

  // Verify health reaches KO and round transition
  await page.evaluate(() => { const g=window.__neonFist.game; g.state='fight'; g.player.wins=0; g.cpu.wins=0; g.round=1; g.cpu.hp=1; g.cpu.state='idle'; g.cpu.hitstun=0; g.cpu.blockHeld=false; g.cpu.invuln=0; g.cpu.move=null; g.player.x=500; g.cpu.x=620; g.player.facing=1; g.player.state='idle'; g.player.move=null; g.player.hitstun=0; });
  await page.keyboard.press('KeyK');
  await page.waitForTimeout(700);
  const ko = await page.evaluate(() => ({state:window.__neonFist.game.state,cpu:window.__neonFist.game.cpu.state,wins:window.__neonFist.game.player.wins}));
  check('KO works', ko.state==='roundEnd' && ko.cpu==='ko' && ko.wins===1, JSON.stringify(ko));
  await page.waitForTimeout(3400);
  check('round 2', (await page.evaluate(() => window.__neonFist.game.round))===2);

  // Force match end on next round
  await page.waitForTimeout(1900);
  await page.evaluate(() => { const g=window.__neonFist.game; g.cpuAI.update=()=>{}; g.player.wins=1; g.state='fight'; g.player.x=500; g.cpu.x=620; g.cpu.hp=1; g.cpu.state='idle'; g.cpu.hitstun=0; g.cpu.blockHeld=false; g.cpu.invuln=0; g.cpu.move=null; g.player.facing=1; g.player.state='idle'; g.player.move=null; g.player.hitstun=0; });
  await page.keyboard.press('KeyK');
  await page.waitForTimeout(5000);
  const end = await page.evaluate(() => ({state:window.__neonFist.game.state,visible:!document.querySelector('#screen-results').classList.contains('hidden'),title:document.querySelector('#results-title').textContent}));
  check('match end results', end.state==='matchEnd'&&end.visible&&end.title==='YOU WIN', JSON.stringify(end));
  await page.screenshot({path:'/tmp/neon-shots/31-results.jpg',type:'jpeg',quality:84});
  await browser.close();
})();

